using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    // Returning customer in the Bronze tier is charged the Bronze price
    [Theory]
    [InlineData(10000, 9500)]
    [InlineData(7, 7)]
    public void Returning_customer_in_the_Bronze_tier_is_charged_the_Bronze_price(int subtotal, int charged)
    {
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotal, LoyaltyTier.Bronze));

        Assert.Equal(charged, quote.TotalCents);
    }
}

